			function setSumNope() {
			    
			    var dsList = app.lookup("dsList");
			    var dsListCol = dsList.getColumnNames();
			    
			    var maleTotSum = 0; /* 남자인원합계*/
			    var femaleTotSum = 0; /* 여자인원합계*/
			    
			    dsListCol.forEach(function(each, idx) {
			        var colNm = each;
			        
			        if (colNm.indexOf("_MALE_NOPE") > -1) {
			            maleTotSum += ValueUtil.fixNumber(dsList.getValue(0, colNm));
			        }
			        if (colNm.indexOf("_FEMALE_NOPE") > -1) {
			            femaleTotSum += ValueUtil.fixNumber(dsList.getValue(0, colNm));
			        }
			    });
			    app.lookup("maleSum").value = maleTotSum;
			    app.lookup("femaleSum").value = femaleTotSum;
			}

